<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Operação de projetos';require APPPATH.'views/admin/includes/native_company_layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'projects/extras'.$q);$hidden=function($action,$type=null,$id=null,$revision=null)use($resource,$kind,$esc,$company_project_extras_csrf,$request_key){$type=$type??$kind;$id=$id??$resource['id'];$revision=$revision??$resource['revision'];foreach(['action'=>$action,'kind'=>$type,'id'=>$id,'revision'=>$revision,'company_project_extras_csrf'=>$company_project_extras_csrf,'request_key'=>$request_key] as $n=>$v)echo '<input type="hidden" name="'.$esc($n).'" value="'.$esc($v).'">';};$labels=['todo'=>'A fazer','in_progress'=>'Em andamento','done'=>'Concluída']; ?>
<section class="company-settings-card"><h1>Operação de projetos</h1><?php if($error){ ?><p class="alert alert-danger" role="alert"><?= $esc($error); ?></p><?php } ?>
<?php if($resource){$id=(int)$resource['id'];$editable=$can_edit&&$resource['_project']['status']==='active'&&($kind==='project'||$resource['status']!=='done'); ?><h2><?= $kind==='task'?'Tarefa: ':'Projeto: '; ?><?= $esc($resource['name']); ?></h2><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,($kind==='task'?'tasks?task=':'projects?project=').$id)); ?>">Abrir dados principais</a></p>
<?= form_open($url());$hidden('follow'); ?><input type="hidden" name="follow" value="<?= $resource['following']?'0':'1'; ?>"><p>Marcação pessoal neste recurso. Nenhuma notificação externa é enviada.</p><button type="submit"><?= $resource['following']?'Deixar de seguir':'Seguir este recurso'; ?></button><?= form_close(); ?>
<h3>Anexos privados</h3><?php if(!$resource['files']){ ?><p>Nenhum anexo ativo.</p><?php } ?><ul><?php foreach($resource['files'] as $file){ ?><li><a href="<?= $esc($url('?kind='.$kind.'&id='.$id.'&file='.$file['file_key'])); ?>"><?= $esc($file['filename']); ?></a> · <?= (int)$file['byte_size']; ?> bytes<?php if($file['mime']==='image/png'){ ?> · <a href="<?= $esc($url('?kind='.$kind.'&id='.$id.'&file='.$file['file_key'].'&preview=1')); ?>">Visualizar PNG</a><?php } ?><?php if($can_edit){ ?><?= form_open($url());$hidden('hide'); ?><input type="hidden" name="file_key" value="<?= $esc($file['file_key']); ?>"><button type="submit">Ocultar arquivo e preservar histórico</button><?= form_close(); ?><?php } ?></li><?php } ?></ul>
<?php if($editable){ ?><?= form_open_multipart($url());$hidden('upload'); ?><label for="project-private-file">PDF (até2 MiB) ou PNG/JPEG (até512 KiB,1600 pixels)</label><input id="project-private-file" type="file" class="form-control" name="project_file" accept=".pdf,.png,.jpg,.jpeg" required><p>Até20 uploads e20 MiB por recurso no histórico, inclusive ocultos. Não há acesso público.</p><button type="submit">Adicionar anexo privado</button><?= form_close(); ?><?php } ?>
<h3>Marcos do projeto</h3><ul><?php foreach($resource['milestones'] as $milestone){ ?><li><?= $esc($milestone['name'].' · '.$milestone['due_date']); ?> · <?= $milestone['done']?'Concluído':'Pendente'; ?><?php if($kind==='project'&&$editable){ ?><?= form_open($url());$hidden('milestone'); ?><input type="hidden" name="milestone_id" value="<?= (int)$milestone['id']; ?>"><input type="hidden" name="milestone[name]" value="<?= $esc($milestone['name']); ?>"><input type="hidden" name="milestone[due_date]" value="<?= $esc($milestone['due_date']); ?>"><input type="hidden" name="milestone[done]" value="<?= $milestone['done']?'0':'1'; ?>"><button type="submit"><?= $milestone['done']?'Reabrir marco':'Concluir marco'; ?></button><?= form_close(); ?><?php } ?></li><?php } ?></ul>
<?php if($kind==='project'&&$editable){ ?><?= form_open($url());$hidden('milestone'); ?><input type="hidden" name="milestone_id" value=""><input type="hidden" name="milestone[done]" value="0"><label for="project-milestone-name">Novo marco</label><input id="project-milestone-name" class="form-control" name="milestone[name]" maxlength="191" required><label for="project-milestone-due">Prazo dentro do projeto</label><input id="project-milestone-due" class="form-control" type="date" name="milestone[due_date]" value="<?= $esc($resource['due_date']); ?>" required><button type="submit">Adicionar marco</button><?= form_close(); ?><?php } ?>
<?php if($kind==='task'&&$editable){ ?><h3>Dependências da tarefa</h3><?= form_open($url());$hidden('dependencies'); ?><p>Selecione tarefas do mesmo projeto que devem estar concluídas antes desta. Ciclos são recusados.</p><?php foreach($resource['board'] as $card){if((int)$card['id']===$id)continue; ?><label><input type="checkbox" name="dependencies[]" value="<?= (int)$card['id']; ?>" <?= in_array((int)$card['id'],$resource['dependencies'],true)?'checked':''; ?>> <?= $esc($card['name'].' · '.$labels[$card['status']]); ?></label><br><?php } ?><button type="submit">Salvar dependências</button><?= form_close(); ?><?php } ?>
<?php if($can_tasks_view){ ?><h3>Quadro do projeto</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px"><?php foreach($labels as $state=>$label){ ?><section aria-label="<?= $esc($label); ?>"><h4><?= $esc($label); ?></h4><?php foreach($resource['board'] as $card){if($card['status']!==$state)continue; ?><article style="padding:12px;border:1px solid #cbd5e1;border-radius:6px;margin-bottom:10px"><p><a href="<?= $esc($url('?kind=task&id='.(int)$card['id'])); ?>"><?= $esc($card['name']); ?></a></p><p><?= $esc($card['due_date']); ?></p><?php if($can_tasks_edit&&$resource['_project']['status']==='active'){ ?><?= form_open($url());$hidden('move','task',$card['id'],$card['revision']); ?><label for="task-board-<?= (int)$card['id']; ?>">Mover para</label><select id="task-board-<?= (int)$card['id']; ?>" class="form-control" name="status"><?php foreach($labels as $value=>$text){ ?><option value="<?= $esc($value); ?>" <?= $value===$state?'selected':''; ?>><?= $esc($text); ?></option><?php } ?></select><button type="submit">Mover tarefa</button><?= form_close(); ?><?php } ?></article><?php } ?></section><?php } ?></div><?php } ?>
<?php }else{ ?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'projects')); ?>">Abrir projetos</a><?php } ?></section><?php require APPPATH.'views/admin/includes/native_company_layout_tail.php'; ?>
